INSERT INTO `quest_template_locale` (`ID`, `locale`, `LogDescription`) VALUES
(7361, 'ruRU', 'Вам поручено убивать игроков-ночных эльфов в Альтеракской долине.$B$BУбейте ночного эльфа и вернитесь к Нажьяку Проклятуну в крепость Северного Волка с отрубленной головой ночного эльфа.'),
(7362, 'ruRU', 'Вам поручено убивать игроков-гномов в Альтеракской долине.$B$BУбейте гнома и вернитесь к Раваку Зловещему Тотему в крепость Северного Волка с пучком гномьих волос.'),
(7363, 'ruRU', 'Вам поручено убивать игроков-людей в Альтеракской долине.$B$BУбейте человека и вернитесь к командиру Луи Филипсу (он ходит между линией фронта и крепостью Северного Волка) с осколком человеческой кости.$B$BЛекарство от участи людей уже близко!'),
(7886, 'ruRU', 'За прошлое задание вы получили талисман заслуг Среброкрылых. Поговорите со мной еще раз, и вы получите награду.'),
(7887, 'ruRU', 'За прошлое задание вы получили талисман заслуг Среброкрылых. Поговорите со мной еще раз, и вы получите награду.'),
(7888, 'ruRU', 'За прошлое задание вы получили талисман заслуг Среброкрылых. Поговорите со мной еще раз, и вы получите награду.'),
(7921, 'ruRU', 'За прошлое задание вы получили талисман заслуг Среброкрылых. Поговорите со мной еще раз, и вы получите награду.'),
(7922, 'ruRU', 'За прошлое задание вы получили знак чести клана Песни Войны. Поговорите со мной еще раз, и вы получите награду.'),
(7923, 'ruRU', 'За прошлое задание вы получили знак чести клана Песни Войны. Поговорите со мной еще раз, и вы получите награду.'),
(7924, 'ruRU', 'За прошлое задание вы получили знак чести клана Песни Войны. Поговорите со мной еще раз, и вы получите награду.'),
(7925, 'ruRU', 'За прошлое задание вы получили знак чести клана Песни Войны. Поговорите со мной еще раз, и вы получите награду.'),
(8081, 'ruRU', 'Победите в сражении за Низину Арати, добудьте ящик с ресурсами Арати и принесите его сержанту Макчисту в Опорный пункт.'),
(8124, 'ruRU', 'Победите в сражении за Низину Арати, добудьте ящик с ресурсами Арати и принесите его ловчему смерти Мортису в Павший Молот.'),
(8157, 'ruRU', 'Победите в сражении за Низину Арати, добудьте ящик с ресурсами Арати и принесите его сержанту Макчисту в Опорный пункт.'),
(8158, 'ruRU', 'Победите в сражении за Низину Арати, добудьте ящик с ресурсами Арати и принесите его сержанту Макчисту в Опорный пункт.'),
(8159, 'ruRU', 'Победите в сражении за Низину Арати, добудьте ящик с ресурсами Арати и принесите его сержанту Макчисту в Опорный пункт.'),
(8163, 'ruRU', 'Победите в сражении за Низину Арати, добудьте ящик с ресурсами Арати и принесите его ловчему смерти Мортису в Павший Молот.'),
(8164, 'ruRU', 'Победите в сражении за Низину Арати, добудьте ящик с ресурсами Арати и принесите его ловчему смерти Мортису в Павший Молот.'),
(8165, 'ruRU', 'Победите в сражении за Низину Арати, добудьте ящик с ресурсами Арати и принесите его ловчему смерти Мортису в Павший Молот.'),
(8267, 'ruRU', 'Принесите ленты самопожертвования капитану Лободробу, чтобы Разведчики смогли наградить вас за то, что вы действовали от нашего имени.'),
(8269, 'ruRU', 'Принесите ленты самопожертвования часовому Дальней Песне, чтобы Часовые смогли наградить вас за то, что вы действовали от нашего имени.'),
(94373, 'ruRU', 'Принесите Тео Молотошторму в Старую Наковальню 2 медвежьих кулона Мерзлогривов.'),
(94374, 'ruRU', 'Найдите Камень Духа и выпейте сапту земли.'),
(94375, 'ruRU', 'Принесите необработанный кварц Тео Молотошторму в Старую Наковальню.'),
(94472, 'ruRU', 'Поговорите с Тео Молотоштормом, чтобы получить еще одну сапту земли.'),
(96608, 'ruRU', 'Посидите у простого костра Эрика и дождитесь, пока вы не получите усиленный отдых.'),
(96628, 'ruRU', 'Доставьте сверток с припасами Эрику Светлому Молоту возле Караноса.'),
(97277, 'ruRU', 'Найдите лагерь Грунда и Гозвина в холмах на северо-западе. Верните журнал механика Гозвина и убейте бродящего снежного леопарда.'),
(97289, 'ruRU', 'Принесите голову барона к телу Отмара в Подгороде.'),
(97290, 'ruRU', 'Доложите о своих выводах мастеру-аптекарю Фаранеллу в Подгороде.'),
(97292, 'ruRU', 'Введите шипящую сыворотку в систему над телом Отмара по поручению главного аптекаря Фаранелла.'),
(98319, 'ruRU', 'Найдите в Серой берлоге горного пехотинца Корнелиуса по поручению горного пехотинца Гретхен.'),
(98321, 'ruRU', 'Соберите в Серой берлоге грузы Огнекремня ($1oa) для Тонгуса Огнекремня в Каранос.'),
(98322, 'ruRU', 'Проведайте горного пехотинца Гретхен к западу от Караноса.'),
(98581, 'ruRU', 'Прочтите древнюю руну и поговорите с Тео Молотоштормом в Старой Наковальне.'),
(99158, 'ruRU', 'Отнесите ящик со свечами отцу Гавину в Приют Туманной Сосны.')
INSERT INTO `quest_template_locale` (`ID`, `locale`, `QuestDescription`) VALUES
(7361, 'ruRU', '<Наджак рычит.>$B$BЗадолго до появления ночных эльфов были тролли. Ночные эльфы произошли от троллей.$B$BИх мятежные нападения на мой народ терпеть нельзя. Олений Шлем хочет стереть нас с лица земли, не оставить и следа от тех, кто его породил. Не бывать этому!$B$BЗа каждого ночного эльфа, которого ты убьешь и обезглавишь, Наджак даст тебе милость племени Черного Копья. Слух о твоих деяниях разнесется по Калимдору и Восточным королевствам. Ступай и служи Черному Копью!'),
(7362, 'ruRU', 'Старейшая Матрона послала меня в эту зону боевых действий изучать другие расы. А точнее, собирать образцы гномов. Магата прежде всего интересуется их живучестью. Да, гномы, хоть и жалко слабы и малы, поразительно выносливы – и в бою, и вне его.$B$BК счастью для тебя, я ищу головорезов, которые выполнят волю Магаты. Принеси мне пучки гномьих волос, и тауренам ты будешь известен как союзник.'),
(7363, 'ruRU', 'Люди просто отвратительны.$B$B<Командир Филипс морщится.>$B$BДа, я солдат клана Северного Волка, но остаюсь слугой Сильваны.$B$BВо время службы я подрабатываю для Темных аптекарей Подгорода.$B$BМне поручено собирать человеческие костяные осколки для лекарства от участи людей.$B$BЯ вправе передать это поручение подчиненным.$B$BНайди их. Убей их. Принеси мне их костяные осколки.'),
(7886, 'ruRU', 'Ты доказал свою ценность для наших усилий в Ущелье Песни Войны. Продолжай помогать нашему делу и приноси мне новые талисманы заслуг. Так ты заслужишь еще больше нашего доверия.'),
(7887, 'ruRU', 'Ты доказал свою ценность для наших усилий в Ущелье Песни Войны. Продолжай помогать нашему делу и приноси мне новые талисманы заслуг. Так ты заслужишь еще больше нашего доверия.'),
(7888, 'ruRU', 'Ты доказал свою ценность для наших усилий в Ущелье Песни Войны. Продолжай помогать нашему делу и приноси мне новые талисманы заслуг. Так ты заслужишь еще больше нашего доверия.'),
(7921, 'ruRU', 'Ты доказал свою ценность для наших усилий в Ущелье Песни Войны. Продолжай помогать нашему делу и приноси мне новые талисманы заслуг. Так ты заслужишь еще больше нашего доверия.'),
(7922, 'ruRU', 'Ты доказал свою ценность для наших усилий в Ущелье Песни Войны. Продолжай бить Среброкрылых Часовых! Приноси мне новые знаки чести!'),
(7923, 'ruRU', 'Ты доказал свою ценность для наших усилий в Ущелье Песни Войны. Продолжай бить Среброкрылых Часовых! Приноси мне новые знаки чести!'),
(7924, 'ruRU', 'Ты доказал свою ценность для наших усилий в Ущелье Песни Войны. Продолжай бить Среброкрылых Часовых! Приноси мне новые знаки чести!'),
(7925, 'ruRU', 'Ты доказал свою ценность для наших усилий в Ущелье Песни Войны. Продолжай бить Среброкрылых Часовых! Приноси мне новые знаки чести!'),
(8081, 'ruRU', 'Войну ведут солдаты, любой из них тебе так скажет. И еще скажет, что бой с плохим снаряжением или на голодный желудок проигран еще до начала!$B$BВот почему так важна Низина Арати. В ней есть ключевые места, где хранятся необходимые ресурсы. Металл, оружие, еда, лес – все это нужно, и все это можно там добыть.$B$BЭтого я и хочу от тебя, $N. Отправляйся в Низину Арати, победи в сражении, удерживая больше баз, чем враг, и принеси мне ящик с ресурсами.'),
(8124, 'ruRU', 'Лига Аратора не жалеет средств, чтобы отвоевать Арати. Они и все расы Альянса стекаются в этот далекий край, намереваясь расширить свои владения от Опорного пункта. Мы должны их остановить, а лучший способ – отобрать у них припасы.$B$BТы можешь нам помочь, $N. Отправляйся в Низину Арати, известную богатыми рудниками, плодородной землей и умелыми мастерами. Захвати и удерживай все базы, какие сможешь, победи в сражении и принеси мне добытые ресурсы.'),
(8157, 'ruRU', 'Войну ведут солдаты, любой из них тебе так скажет. И еще скажет, что бой с плохим снаряжением или на голодный желудок проигран еще до начала!$B$BВот почему так важна Низина Арати. В ней есть ключевые места, где хранятся необходимые ресурсы. Металл, оружие, еда, лес – все это нужно, и все это можно там добыть.$B$BЭтого я и хочу от тебя, $N. Отправляйся в Низину Арати, победи в сражении, удерживая больше баз, чем враг, и принеси мне ящик с ресурсами.'),
(8158, 'ruRU', 'Войну ведут солдаты, любой из них тебе так скажет. И еще скажет, что бой с плохим снаряжением или на голодный желудок проигран еще до начала!$B$BВот почему так важна Низина Арати. В ней есть ключевые места, где хранятся необходимые ресурсы. Металл, оружие, еда, лес – все это нужно, и все это можно там добыть.$B$BЭтого я и хочу от тебя, $N. Отправляйся в Низину Арати, победи в сражении, удерживая больше баз, чем враг, и принеси мне ящик с ресурсами.'),
(8159, 'ruRU', 'Войну ведут солдаты, любой из них тебе так скажет. И еще скажет, что бой с плохим снаряжением или на голодный желудок проигран еще до начала!$B$BВот почему так важна Низина Арати. В ней есть ключевые места, где хранятся необходимые ресурсы. Металл, оружие, еда, лес – все это нужно, и все это можно там добыть.$B$BЭтого я и хочу от тебя, $N. Отправляйся в Низину Арати, победи в сражении, удерживая больше баз, чем враг, и принеси мне ящик с ресурсами.'),
(8163, 'ruRU', 'Лига Аратора не жалеет средств, чтобы отвоевать Арати. Они и все расы Альянса стекаются в этот далекий край, намереваясь расширить свои владения от Опорного пункта. Мы должны их остановить, а лучший способ – отобрать у них припасы.$B$BТы можешь нам помочь, $N. Отправляйся в Низину Арати, известную богатыми рудниками, плодородной землей и умелыми мастерами. Захвати и удерживай все базы, какие сможешь, победи в сражении и принеси мне добытые ресурсы.'),
(8164, 'ruRU', 'Лига Аратора не жалеет средств, чтобы отвоевать Арати. Они и все расы Альянса стекаются в этот далекий край, намереваясь расширить свои владения от Опорного пункта. Мы должны их остановить, а лучший способ – отобрать у них припасы.$B$BТы можешь нам помочь, $N. Отправляйся в Низину Арати, известную богатыми рудниками, плодородной землей и умелыми мастерами. Захвати и удерживай все базы, какие сможешь, победи в сражении и принеси мне добытые ресурсы.'),
(8165, 'ruRU', 'Лига Аратора не жалеет средств, чтобы отвоевать Арати. Они и все расы Альянса стекаются в этот далекий край, намереваясь расширить свои владения от Опорного пункта. Мы должны их остановить, а лучший способ – отобрать у них припасы.$B$BТы можешь нам помочь, $N. Отправляйся в Низину Арати, известную богатыми рудниками, плодородной землей и умелыми мастерами. Захвати и удерживай все базы, какие сможешь, победи в сражении и принеси мне добытые ресурсы.'),
(8267, 'ruRU', 'Я знаю, что в Ущелье Песни Войны порой нелегко выйти победителем. И все же твои усилия ради нас, даже без победы, очень важны.$B$BЕсли ты пройдешь одно из испытаний в Ущелье Песни Войны, но не одержишь победы, ты все равно получишь ленту самопожертвования. Принеси ее мне, чтобы Разведчики смогли наградить тебя за то, что ты действовал от нашего имени… даже если на этот раз победа не далась.'),
(8269, 'ruRU', 'Я знаю, что в Ущелье Песни Войны порой нелегко выйти победителем. И все же твои усилия ради нас, даже без победы, очень важны.$B$BЕсли ты пройдешь одно из испытаний в Ущелье Песни Войны, но не одержишь победы, ты все равно получишь ленту самопожертвования. Принеси ее мне, чтобы Часовые смогли наградить тебя за то, что ты действовал от нашего имени… даже если на этот раз победа не далась.'),
(94373, 'ruRU', 'Ага, пришло время, молодой шаман. Ты стал крепким и стойким, как камень под нашими сапогами. Раз ты встал на путь шамана, значит, в тебе есть мудрость горы, хоть ты и не успел себя показать. В тебе есть каменная стойкость, чтобы пройти путем Земли.  Но чтобы заслужить ее милость, надо предстать перед ней как подобает. К югу отсюда в пещере живут тролли из племени Мерзлогривов.  Принеси мне два ожерелья, которые они носят, – их делают из медведей-ледолапов. Тогда и поговорим о твоем будущем.'),
(94374, 'ruRU', 'Ага, сапта – это зелье, сваренное с помощью магии, оно связывает наш дух со стихиями. Рецепт знают лишь немногие шаманы, и слабым духом оно не по плечу. Выпей его, и увидишь то, что другим не дано. И запомни: пить его можно только в священном месте.  Ступай на север, к Камню Духа, он стоит в конце потайной тропы в горах. Выпей сапту там… и увидишь, что покажет тебе земля.'),
(94375, 'ruRU', 'Возьми у меня этот необработанный кварц и отнеси Тео Молотошторму в доказательство нашей встречи. Он сделает для тебя тотем, и этот камешек станет его сердцем. Каким бы маленьким он ни казался, ты поймешь, что размер не важен и что даже самое малое переживет многое.  Будь терпелив, $n. Оставайся сильным. И ищи мудрость. Этого земля и просит от тебя. В конце концов ты станешь единым целым с землей – уважай ее, и она будет уважать тебя.'),
(96608, 'ruRU', 'Приветствую, $c. Сразу видно, что ты искатель приключений. Это хорошо. Миру нужно больше таких беспокойных душ, как мы, – тех, кто ищет удачу и славу.  Чтобы преуспеть в этом деле, придется научиться выживать в глуши. Не знаю, как у тебя с походными навыками, но кое-чему я тебя научу, если захочешь.  Присаживайся у огня и устраивайся поудобнее. Я все объясню.'),
(96628, 'ruRU', 'Подожди, $n. У меня есть к тебе еще одна просьба, прежде чем ты пойдешь в этот туннель.  Мои горные пехотинцы сообщили, что у самого Караноса появился какой-то искатель приключений. Не мог бы ты отнести ему эти припасы?'),
(97277, 'ruRU', 'Эй, я как раз отвернулся, готовил жаркое из кабана, и тут мой приятель Гозвин заорал, будто его убивают!  Я успел заметить только жуткие клыки и размытое пятно. И какие лапищи! Снежный леопард тащил добычу – бедного гнома. Я схватил ружье и выстрелил поверх зверя. Он бросил Гоза и умчался.  К счастью, он только глубоко поцарапал старину Гоза.  Возвращайся в лагерь в северо-западных холмах и принеси журнал механика Гозвина. И если увидишь этого леопарда – убей его!'),
(97289, 'ruRU', 'Головы для измененных мы делаем постоянно, но эта особенная. Когда-то она принадлежала верховному маршалу Альянса. Крайне неприятному типу. Отмар, если не ошибаюсь. Темная Госпожа лично имела удовольствие с ним расправиться.  О, какие тайны он мог бы поведать, если бы умел говорить. А он умеет! Если приставить голову к подходящему телу.  Положи ее рядом с телом в соседней комнате. Но не присоединяй. Пока рано.'),
(97290, 'ruRU', 'Ты… мерзость…  С чего мне… тебе помогать…  Прочь…'),
(97292, 'ruRU', 'Я составил чудесную сыворотку, которая, несомненно, окажется для нашего нового гостя весьма… бодрящей.  Возьми. Влей ее в механизм, что капает у него над головой. Посмотрим, не удастся ли убедить его, что в его интересах служить верой и правдой.  И постарайся не уронить. Нового помощника мне не потянуть.'),
(98319, 'ruRU', 'Мало нам было троллей, так еще горы кишмя кишат вендиго! Они обычно сидят по своим пещерам, а тут вдруг расплодились, как кролики. Теперь вот набились в Серую берлогу к северу отсюда.  Чтобы получить отчет Белобородого, придется разыскать моего напарника Корнелиуса. Этот болван слишком разгорячился и полез туда напролом. Храбрый, но глупый.  Иди в пещеру и узнай, где он. И не стесняйся перебить там зверей.'),
(98321, 'ruRU', 'Хо-хо! Приятно видеть $r, который не боится замарать руки.  Если ищешь работу, то у меня сейчас туговато с припасами. Самый надежный наш рудник захватили вендиго, и пещеру пришлось бросить. Шахтеры удирали так, что побросали все!  Слышь, загляни-ка в Серую берлогу на западе и поищи наши пропавшие грузы. Здорово нас выручишь.'),
(98322, 'ruRU', 'Лазить по темным пещерам – дело искателей приключений. Моя работа – писать отчеты и отправлять их в Стальгорн.  Вот только один из моих отчетов… не вернулся с отчетом. Я просил нескольких горных пехотинцев разузнать побольше про вендиго, но от них ни слуху ни духу.  Раз уж ты все равно собрался пройтись, загляни к горному пехотинцу Гретхен, она сразу за городом на запад. Я и так уже опаздываю!'),
(98581, 'ruRU', 'Пока ты мне помогал, мне передали эту руну для тебя. Прочти ее, когда будет время. Судя по стилю надписей, как у Громового Молота, ее прислал наставник шаманов Тео Молотошторм. Взгляни на нее и при случае найди его в Старой Наковальне.'),
(99158, 'ruRU', 'В горах живет священник из организации под названием Серебряный Рассвет. Это святой орден, который выискивает и уничтожает все нечестивое и противоестественное.  Но отец Гэвин больше из тех, кто предпочитает помогать и исцелять, а не хвататься за оружие. Он привел в порядок старое здание и устроил там место отдыха для путников – Приют Туманной Сосны. У меня есть партия святых свечей, которую нужно ему передать. Не отнесешь, если будешь проходить мимо?')
