INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`) VALUES
(171, 'ruRU', 'Да благословят тебя небеса, $N. Ты $Gсделал:сделала; для Рэндиса больше, чем многие согласились бы сделать.  Спасибо тебе – ты яркая звезда на небосклоне Альянса.$B$BПожалуйста, если найдешь время, заходи к нам еще. Рэндису это было бы приятно, да и мне тоже.$B$BРэндису так понравилось с тобой, $N. Он хотел подарить тебе одного из своих любимых питомцев на память.'),
(558, 'ruRU', 'ВАУ!  Ты $Gраздобыл:раздобыла; для меня автограф леди Джайны! Огромное спасибо! И ничего себе… она написала личное послание – мне! Я знал, что она будет очень классной, и, может быть, когда-нибудь я сам ее поблагодарю… когда стану героем Альянса!$B$BТы самый лучший, $N. Спасибо, что ты так добр ко мне.'),
(960, 'ruRU', 'Я размышляю о твоем задании, $N. Размышляю о том, зачем сюда явились Сумеречный Молот и наги.$B$BКогда будешь готов, используй флакон прозрения, чтобы создать чашу прозрения. Потом свяжись со мной через эту чашу.$B$BЕсли ты потерял флакон прозрения, вот тебе другой.'),
(1479, 'ruRU', 'Ух ты, это было круче, чем я себе представлял, – Купина Вечности! Я не думал, что она такая огромная, а она такая! Ты видел птицу на самой верхушке?! Интересно, как они заставили ветви так расти!$B$BСпасибо, что $Gотвел:отвела; меня в Дарнас, $N. Ты замечательный!'),
(1658, 'ruRU', 'Молодец, $N. Праздник Плетеного человека будет сплошной бедой, пока мерзкие Отрекшиеся бродят среди руин Лордерона. Это НЕ достойная дань памяти когда-то гордого королевства, поверь мне…$B$BВот немного монет на ремонт, если понадобится, а еще, в духе праздника, я $Gположил:положила; несколько лакомств, которые тебе понравятся. Счастливого Тыквовина – давай постараемся, чтобы в Южнобережье все прошло как можно спокойнее.'),
(1678, 'ruRU', 'Да уж, Веджрек был тот еще урод, а? Отлично, $N! Ты на многое способен, а теперь начнем твой урок…$b$bМожет, ты и не знаешь, но для $C крепкая защита очень важна. Она помогает устоять там, где другие пали бы, а именно этого ждут от тебя союзники.'),
(1803, 'ruRU', 'Так-так-так! Что это у нас тут?$b$bВпечатляет, $n. Я не думал, что такое возможно, но вот он, у меня в руках – полный Фолиант Заговора.$b$bПозволь мне перелистать его страницы всего на минутку, прежде чем ты отправишься дальше.'),
(3092, 'ruRU', 'И моя задача – подготовить тебя, обучив основам нашего ремесла: как приручать питомца, как стрелять из ружья и многим другим навыкам, которые тебе пригодятся.$b$bОхотники – важная часть нашей традиции и истории, $N. Не забывай, как ты $Gважен:важна; для племени. Если ты будешь хорошо служить нашему народу, тебя будут уважать и чтить.'),
(4485, 'ruRU', 'А, ты $Gвернулся:вернулась; в Собор, $n. Хорошо. В последнее время многое произошло, и мне понадобится твоя помощь, если ты окажешься $Gдостоин:достойна;.$b$bВокруг много коварных врагов. Мне нужна твоя помощь, чтобы остановить их.'),
(4486, 'ruRU', 'А, ты $Gвернулся:вернулась; в Собор, $n. Хорошо. В последнее время многое произошло, и мне понадобится твоя помощь, если ты окажешься $Gдостоин:достойна;.$b$bВокруг много коварных врагов. Мне нужна твоя помощь, чтобы остановить их.'),
(4963, 'ruRU', 'А, дух инфернала. Молодец, $N.$B$BКогда у меня будут и дух, и очищенная сфера, я соединю их для тебя, но не раньше.'),
(5237, 'ruRU', '$N, твое успешное перенастройка котлов – огромная победа для нас!$B$B<Командир откашливается и начинает громко возглашать.>$B$BПусть слышат все, кто находится рядом: за службу Королевству Штормград и всему Альянсу, превосходящую все, чего требовал долг, перед лицом несметных врагов и невероятной опасности, добавлю, я награждаю $N этим и выражаю $Gему:ей; нашу вечную благодарность как истинному герою Альянса. Слава герою, говорю я!'),
(5238, 'ruRU', '$N, твое успешное перенастройка котлов – огромная победа для нас!$B$B<Верховный палач откашливается и начинает громко возглашать.>$B$BПусть слышат все, кто находится рядом: за службу Отрекшимся и всей Орде, превосходящую все ожидания, перед лицом несметных врагов и невероятной опасности, добавлю, я награждаю $N этим и выражаю $Gему:ей; нашу вечную благодарность как истинному герою Орды. Ура!'),
(5505, 'ruRU', 'Ну вот, $N, вот он – готовый ключ-скелет. Я почти уверен, что этот ключ позволит тебе войти в Некроситет. Но убедиться в этом можно только одним способом. Не откладывай, проверь его сразу.$B$BУдачи, могучий герой. Неси свет во тьму и дальше!'),
(5511, 'ruRU', 'Ну вот, $N, вот он – готовый ключ-скелет. Я почти уверен, что этот ключ позволит тебе войти в Некроситет. Но убедиться в этом можно только одним способом. Не откладывай, проверь его сразу.$B$BУдачи, могучий герой. Пусть твои победы приносят тебе славу и силу, пока ты громишь Некроситет!'),
(5647, 'ruRU', 'Из тебя выйдет отличный $c, $n. Так держать!$b$nТы уже $Gпоказал:показала;, что $Gготов:готова; к бою. Может, пора научить тебя чему-нибудь еще.'),
(6722, 'ruRU', 'Да, пришло время тебя учить…'),
(7365, 'ruRU', 'Спасибо, $N. Воздух стал немного чище.'),
(7382, 'ruRU', 'Молодец, $n. Теперь даже самая могучая магия не воскресит Коррака. Ты $Gизбавился:избавилась; от серьезной угрозы Альтеракскую долину, солдат.'),
(7402, 'ruRU', 'Хорошо, $N. Жду мышек.'),
(7425, 'ruRU', 'Спасибо, $N. Воздух стал немного чище.'),
(7428, 'ruRU', 'Хорошо, $N. Жду мышек.'),
(7493, 'ruRU', 'Убийца драконов и опытный кожевник? Ты не перестаешь меня удивлять, герой. Я польщен.$B$BПрими то, чему я сейчас научу тебя. Эти знания окажутся бесценными, если ты хочешь уничтожить то, что осталось от черных драконов.$B$BСоздай плащ из чешуи королевы стаи. Он защитит тебя и твоих союзников от пламенного дыхания Повелителя Черной горы… Нефариана.'),
(7497, 'ruRU', 'Убийца драконов и опытный кожевник? Ты не перестаешь меня удивлять, герой. Я польщен.$B$BПрими то, чему я сейчас научу тебя. Эти знания окажутся бесценными, если ты хочешь уничтожить то, что осталось от черных драконов.$B$BСоздай плащ из чешуи королевы стаи. Он защитит тебя и твоих союзников от пламенного дыхания Повелителя Черной горы… Нефариана.'),
(7652, 'ruRU', 'Слушай, приятель, есть у меня выгодное предложение.$B$BХочу сбыть кое-какие рецепты императорских латных доспехов, и мне нужен тот, кто возьмет эту ношу на себя. Взамен прошу только слитки тория. Идет?'),
(7660, 'ruRU', 'Принеси мне своего старого быстрого волка, и я обменяю его на волка из нового выводка.   Новый волк будет так же быстр, как старый, но выглядеть будет иначе.   Взгляни на быстрых волков, что уже бегают тут во дворе, и увидишь, как он будет выглядеть.'),
(7661, 'ruRU', 'Принеси мне своего старого быстрого волка, и я обменяю его на волка из нового выводка.   Новый волк будет так же быстр, как старый, но выглядеть будет иначе.   Взгляни на быстрых волков, что уже бегают тут во дворе, и увидишь, как он будет выглядеть.'),
(7662, 'ruRU', 'Принеси мне своего старого кодо, и я обменяю его на кодо из нового стада.   Новый кодо будет так же быстр, как старый, но выглядеть будет иначе.   Взгляни на больших кодо, что уже бродят тут во дворе, и выбери себе по вкусу.'),
(7663, 'ruRU', 'Принеси мне своего старого кодо, и я обменяю его на кодо из нового стада.   Новый кодо будет так же быстр, как старый, но выглядеть будет иначе.   Взгляни на больших кодо, что уже бродят тут во дворе, и выбери себе по вкусу.'),
(7664, 'ruRU', 'Принеси мне старого ящера, а я дам тебе нового, с только что наточенными когтями!  Новый ящер будет так же быстр, как старый, но выглядеть будет иначе.   Взгляни на быстрых ящеров здесь, и выберешь, какой тебе нравится.'),
(7665, 'ruRU', 'Принеси мне старого ящера, а я дам тебе нового, с только что наточенными когтями!  Новый ящер будет так же быстр, как старый, но выглядеть будет иначе.   Взгляни на быстрых ящеров здесь, и выберешь, какой тебе нравится.'),
(7668, 'ruRU', 'Вот это победа, достойная того, чтобы ею насладиться, $N! Гибель Темного Губителя должна восстановить хрупкие оковы, на которых держится мир духов.$B$BТы $Gсделал:сделала; гораздо больше, чем у тебя просили, даже не думая о награде. Ты поистине достойный $C, друг мой.$B$BЯ знаю, что спасение мира духов само по себе должно быть наградой, но прошу – прими этот скромный дар в знак моей благодарности.'),
(7671, 'ruRU', 'Принеси мне своего старого ледяного саблезуба, и я обменяю его на саблезуба из нового выводка.   Новый быстрый саблезуб будет так же быстр, как старый, но выглядеть будет иначе.   Взгляни на быстрых саблезубов, что уже бродят тут во дворе, и увидишь, как он будет выглядеть.'),
(7672, 'ruRU', 'Принеси мне своего старого ночного саблезуба, и я обменяю его на саблезуба из нового выводка.   Новый быстрый саблезуб будет так же быстр, как старый, но выглядеть будет иначе.   Взгляни на быстрых саблезубов, что уже бродят тут во дворе, и увидишь, как он будет выглядеть.'),
(7673, 'ruRU', 'Приведи мне своего старого барана, и я обменяю его на барана из нового стада!  Новый баран будет так же быстр, как твой старый, но выглядеть будет иначе.   Взгляни на быстрых баранов здесь, и выберешь, какой тебе по душе.'),
(7674, 'ruRU', 'Приведи мне своего старого барана, и я обменяю его на барана из нового стада!  Новый баран будет так же быстр, как твой старый, но выглядеть будет иначе.   Взгляни на быстрых баранов здесь, и выберешь, какой тебе по душе.'),
(7675, 'ruRU', 'Если ты все еще ездишь на старом ледяном голубом механодолгоноге мод. A, самое время обменять его на новую модель. Новый быстрый механодолгоног сохранит всю скорость прежнего, но будет выглядеть совсем иначе. Взгляни на быстрых механодолгоногов, и выберешь тот, что приглянется.'),
(7676, 'ruRU', 'Если ты все еще ездишь на старом белом механодолгоноге мод. A, самое время обменять его на новую модель. Новый быстрый механодолгоног сохранит всю скорость прежнего, но будет выглядеть совсем иначе. Взгляни на быстрых механодолгоногов, и выберешь тот, что приглянется.'),
(7677, 'ruRU', 'Если приведешь мне своего белого жеребца, я обменяю его на коня из нового табуна. Новый конь будет так же быстр, как старый, но выглядеть будет иначе. Взгляни на быстрых скакунов, и увидишь, как он будет выглядеть.'),
(7678, 'ruRU', 'Если приведешь мне своего паломино, я обменяю его на коня из нового табуна. Новый конь будет так же быстр, как старый, но выглядеть будет иначе. Взгляни на быстрых скакунов, и увидишь, как он будет выглядеть.'),
(7788, 'ruRU', 'Ты доказал свою ценность для наших усилий в Ущелье Песни Войны. Продолжай помогать нашему делу и приноси мне новые знаки чести. Так ты заслужишь еще больше нашего доверия.'),
(7871, 'ruRU', 'Ты доказал свою ценность для наших усилий в Ущелье Песни Войны. Продолжай помогать нашему делу и приноси мне новые знаки чести. Так ты заслужишь еще больше нашего доверия.'),
(7872, 'ruRU', 'Ты доказал свою ценность для наших усилий в Ущелье Песни Войны. Продолжай помогать нашему делу и приноси мне новые знаки чести. Так ты заслужишь еще больше нашего доверия.'),
(7873, 'ruRU', 'Ты доказал свою ценность для наших усилий в Ущелье Песни Войны. Продолжай помогать нашему делу и приноси мне новые знаки чести. Так ты заслужишь еще больше нашего доверия.'),
(8123, 'ruRU', '<Ловчий смерти Мортис улыбается.>$b$bЕще один решающий удар по нашим врагам, $n. Благодаря твоим деяниям Осквернители скоро возьмут Низину Арати в свои руки. '),
(8160, 'ruRU', '<Ловчий смерти Мортис улыбается.>$b$bЕще один решающий удар по нашим врагам, $n. Благодаря твоим деяниям Осквернители скоро возьмут Низину Арати в свои руки. '),
(8161, 'ruRU', '<Ловчий смерти Мортис улыбается.>$b$bЕще один решающий удар по нашим врагам, $n. Благодаря твоим деяниям Осквернители скоро возьмут Низину Арати в свои руки. '),
(8162, 'ruRU', '<Ловчий смерти Мортис улыбается.>$b$bЕще один решающий удар по нашим врагам, $n. Благодаря твоим деяниям Осквернители скоро возьмут Низину Арати в свои руки. '),
(8259, 'ruRU', 'А, $n… твои усилия против Темного Губителя были необыкновенными – и, добавлю, заслуживали куда лучшей награды, чем ты $Gполучил:получила;.  Прими этот шлем как дополнительный подарок за твои достижения в Некроситете.$B$BЕще раз спасибо.'),
(8291, 'ruRU', 'Ты доказал свою ценность для наших усилий в Ущелье Песни Войны. Продолжай помогать нашему делу и приноси мне новые знаки чести. Так ты заслужишь еще больше нашего доверия.'),
(8299, 'ruRU', '<Ловчий смерти Мортис улыбается.>$b$bЕще один решающий удар по нашим врагам, $n. Благодаря твоим деяниям Осквернители скоро возьмут Низину Арати в свои руки. '),
(8352, 'ruRU', 'Ты… ты это $Gсделал:сделала;! Ты $Gсделал:сделала; это, $N! Вот! Возьми. Это самый большой сундук, какой у нас был, и я набил его лучшим из того, что мы нашли.'),
(8411, 'ruRU', 'Вот эти стихии мне и нужны. Теперь можно говорить.'),
(8565, 'ruRU', 'А, да! Конечно, мы не забыли о твоих прошлых достижениях в Низине Арати.'),
(8566, 'ruRU', 'А, да! Конечно, мы не забыли о твоих прошлых достижениях в Низине Арати.'),
(8567, 'ruRU', 'А, да! Конечно, мы не забыли о твоих прошлых достижениях в Ущелье Песни Войны.'),
(8568, 'ruRU', 'А, да! Конечно, мы не забыли о твоих прошлых достижениях в Ущелье Песни Войны.'),
(8569, 'ruRU', 'А, да! Конечно, мы не забыли о твоих прошлых достижениях в Ущелье Песни Войны.'),
(8570, 'ruRU', 'А, да! Конечно, мы не забыли о твоих прошлых достижениях в Ущелье Песни Войны.'),
(8612, 'ruRU', 'Пахнет так, будто ты или кто-то из твоих знакомых отменно готовит, $N. От этих постных волчьих стейков слюнки текут; полагаю, если парочка пропадет, никто и не заметит. В общем, молодец. Я позабочусь, чтобы их как следует упаковали и они не испортились.$B$BЕсли найдешь еще, ты знаешь, где меня искать.'),
(8636, 'ruRU', 'Все живое обречено умереть и вернуться в землю, но дух вечен.  Желаю тебе всего хорошего, $N, и дарю тебе этот знак…'),
(8745, 'ruRU', 'Приветствую, защитник. Я Джонатан, хранитель священного гонга и вечный страж Бронзовой стаи.$B$BСам Вневременный наделил меня силой подарить тебе предмет на твой выбор из его вневременной сокровищницы. Пусть он поможет тебе в сражениях с К''Туном.'),
(9257, 'ruRU', 'Значение этого достижения трудно переоценить, $N. Ты $Gсовершил:совершила; то, что большинство сочло бы невозможным. Но так было суждено. Посох сделал свой выбор…'),
(9269, 'ruRU', 'Значение этого достижения трудно переоценить, $N. Ты $Gсовершил:совершила; то, что большинство сочло бы невозможным. Но так было суждено. Посох сделал свой выбор…'),
(9270, 'ruRU', 'Значение этого достижения трудно переоценить, $N. Ты $Gсовершил:совершила; то, что большинство сочло бы невозможным. Но так было суждено. Посох сделал свой выбор…'),
(9271, 'ruRU', 'Значение этого достижения трудно переоценить, $N. Ты $Gсовершил:совершила; то, что большинство сочло бы невозможным. Но так было суждено. Посох сделал свой выбор…'),
(92401, 'ruRU', 'То, о чем я просила, было несправедливо, и никто не осудил бы тебя, если бы ты просто ушел. Спасибо, незнакомец. Мне нечем отплатить тебе тем же, но надеюсь, что-нибудь из этого тебе подойдет.\r\n\r\nНадеюсь, наши пути еще пересекутся и не при таких печальных обстоятельствах.'),
(92421, 'ruRU', 'Пусть те, кто лишился милости Королевы-банши, встретят наше правосудие!\r\n\r\nС этими частями наши братья и сестры получат надежду дожить до другого дня. Ты делаешь честь капитану Бандариону.'),
(94911, 'ruRU', 'Высокий эльф говорит со мной… в Громовом Утесе. Чудеса, да и только!\r\n\r\nЧто ж, повелитель ветра, позволь мне вместе с нашими братьями и сестрами из Служителей Земли поприветствовать тебя в Азероте. Мои собратья-друиды из Круга Кенария могут многому тебя научить, дитя природы.'),
(94913, 'ruRU', 'О, вижу, ты уже овладел облик медведя. Хорошо, хорошо. Ты на верном пути, юный друид.'),
(96339, 'ruRU', 'Подождите, вы сказали, вас зовут $n?\r\n\r\n$n! Я так рад наконец с вами познакомиться. Сюда доставили посылку на ваше имя, и мне заверили, что вы рано или поздно за ней придете. Я пытался объяснить, что у нас такого не делают, но не успел и слова сказать, как они уже ушли!\r\n\r\nИ вы вовремя: ее бы свалили в кучу с прочим хламом, который я каждую ночь выбрасываю в море.\r\n\r\nЧто? Мы все так делаем. Ох, просто забирайте свою посылку и идите!'),
(96340, 'ruRU', 'Подождите, вы сказали, вас зовут $n?\r\n\r\n$n! Я так рад наконец с вами познакомиться. Сюда доставили посылку на ваше имя, и мне заверили, что вы рано или поздно за ней придете. Я пытался объяснить, что у нас такого не делают, но не успел и слова сказать, как они уже ушли!\r\n\r\nИ вы вовремя: ее бы свалили в кучу с прочим хламом, который я каждую ночь выбрасываю в море.\r\n\r\nЧто? Мы все так делаем. Ох, просто забирайте свою посылку и идите!'),
(96341, 'ruRU', 'Подождите, вы сказали, вас зовут $n?\r\n\r\n$n! Я так рад наконец с вами познакомиться. Сюда доставили посылку на ваше имя, и мне заверили, что вы рано или поздно за ней придете. Я пытался объяснить, что у нас такого не делают, но не успел и слова сказать, как они уже ушли!\r\n\r\nИ вы вовремя: ее бы свалили в кучу с прочим хламом, который я каждую ночь выбрасываю в море.\r\n\r\nЧто? Мы все так делаем. Ох, просто забирайте свою посылку и идите!'),
(96342, 'ruRU', 'Подождите, вы сказали, вас зовут $n?\r\n\r\n$n! Я так рад наконец с вами познакомиться. Сюда доставили посылку на ваше имя, и мне заверили, что вы рано или поздно за ней придете. Я пытался объяснить, что у нас такого не делают, но не успел и слова сказать, как они уже ушли!\r\n\r\nИ вы вовремя: ее бы свалили в кучу с прочим хламом, который я каждую ночь выбрасываю в море.\r\n\r\nЧто? Мы все так делаем. Ох, просто забирайте свою посылку и идите!'),
(96394, 'ruRU', 'А, хорошо, значит, готово. Не могу же я допустить, чтобы остальные смотрители отказывались заходить в зал и выполнять свои обязанности из-за «призраков» и «злых мертвецов», верно?'),
(97277, 'ruRU', 'Ага, не удивлюсь, что этот снежный леопард устроил себе пир из кабана, которого мы собирались жарить!\r\n\r\nУ Гоза теперь одной заботой меньше – ты $Gвернул:вернула; его журнал. Может, теперь он сможет направить все силы на то, чтобы встать на ноги.\r\n\r\nСпасибо, $n. Вот, возьми кое-что в знак моей признательности – за то, что $Gпрошел:прошла; такой путь и $Gзащитил:защитила; холмы.'),
(97891, 'ruRU', 'А, чудесно! Я как раз ждал зелье от Алессандро. Последние шесть, что он присылал, по дороге испортились, а ты $Gуспел:успела; вовремя!\r\n\r\nВот, возьми за труды. На этом пока все, если только у тебя нет ко мне других дел?\r\n\r\nЕсли нет, исчезни, чтобы я мог продолжить свои опыты без помех.'),
(97972, 'ruRU', 'Вот и все, теперь ты можешь сделать собственное Развевающееся знамя. Большинство людей не любят, когда лагеря разбивают посреди города, так что тебе придется отправиться в глушь, если захочешь его испытать.\r\n\r\nИ помни: без костра лагерь не лагерь. Он понадобится тебе, прежде чем ты разобьешь лагерь. Большинство поваров умеют разводить огонь. Если ты еще не $Gсделал:сделала; этого, зайди к кому-нибудь, кто обучает кулинарному делу, и освой основы.'),
(98322, 'ruRU', 'Белобород прислал тебя, да?\r\n\r\nОтчет его я получил, точно. Вся эта история – сплошной бардак!'),
(98581, 'ruRU', 'Шаманскую науку издавна хранил клан Громового Молота, а теперь ее приняли и дворфы Бронзобородов. Я здесь, чтобы распространять эти учения и помогать новым шаманам, которые познают пути стихий. Приходи ко мне, если нужно больше уроков по заклинаниям земли, воздуха, огня и воды.'),
(99127, 'ruRU', 'Все ловушки такие? Похоже, наши новые соседи-вредители разрушают больше, чем мы думали. Если мы ничего не предпримем, я разорюсь.')
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`) VALUES
(12, 'ruRU', 'Видимо, я неясно выразился, послушник. Чтобы доказать, что ты достоин служить Народному ополчению и Свету, ты должен убить 15 зверолов и 15 контрабандистов из братства Справедливости, а потом вернуться ко мне.'),
(25, 'ruRU', 'Уже $Gвернулся:вернулась;? Как там обстановка – все теперь спокойно, благодаря тебе?'),
(62, 'ruRU', 'Что ты можешь доложить, $N? Ты $Gпобывал:побывала; в Руднике Подземных глубин?'),
(190, 'ruRU', 'Настоящий охотник на пантер сейчас бродил бы по полям и выслеживал добычу. Покажи упорство в достижении цели, $c, и отправляйся обратно.'),
(192, 'ruRU', 'Что ты тут делаешь, $N!  Тебе положено ползать по зарослям и убивать 10 тенебрюхих пантер. Я думал, ты считаешь себя великим охотником на крупную дичь?'),
(195, 'ruRU', 'Настоящий охотник сосредоточен на добыче. А ты, друг мой, больше занят болтовней у костра. А ну марш убивать 10 ящеров-кнутохвостов, пока я сам не вычистил от них всю эту проклятую джунгли одним махом.'),
(201, 'ruRU', 'Ну что? Удалось отыскать лагерь?'),
(216, 'ruRU', 'Ты уже $Gвступил:вступила; в бой с племенем Колючего Меха? Если путь между нашими базами будет свободен, наши шансы захватить весь Ясеневый лес заметно вырастут.'),
(370, 'ruRU', 'Юный $c, тебе не стоит терять время в Брилле, когда твой народ нуждается в бойцах. Бери оружие и отправляйся на юго-запад, к разрушенной башне, и убей капитана Перрин, а с ней 3 ревнителей и 3 миссионеров из Алого ордена. Мы загоним Алый орден, как скот, прямо на бойню.'),
(371, 'ruRU', 'Вижу, ты $Gвернулся:вернулась;, но задание не выполнено. Может, тебя устраивает, что простые люди мешают замыслам Темной Госпожи? Или ты все же откликнешься на зов долга и убьешь капитана Вакона и его шайку келейников Алого ордена!'),
(409, 'ruRU', 'Я жду доказательства твоей преданности, $C.'),
(435, 'ruRU', 'Говори коротко. Вокруг много опасностей, и мы не можем стоять без дела и вести беседы.'),
(527, 'ruRU', 'Как верховный палач Таррена Милла, подчиняющийся непосредственно Вариматразу и Темной Госпоже, ты обязан выполнять мои приказы.$b$bМожет, ты относишься к этой войне с Альянсом легкомысленно? Если так, я отрублю тебе голову прямо здесь и сейчас. А иначе отправляйся на запад, в город Хилсбрад, и сражайся с людьми, как приказано.$b$bСвободен.'),
(536, 'ruRU', 'Еще эля, пожалуйста, предыдущий куда-то испарился!$b$bСвет, и долго мне тут торчать?$b$bА, это ты, $n. Ты уже $Gубил:убила; тех мурлоков?'),
(545, 'ruRU', 'Ты уже проредил даларанские патрули вокруг их руин?'),
(579, 'ruRU', 'Король Андуин придает огромное значение просвещению, а потому выделил средства на то, чтобы копии разных фолиантов и записей были доступны всем. Все очень просто. Принеси мне библиотечный талон, и я выдам тебе копию одной из имеющихся книг.'),
(608, 'ruRU', 'В чем дело, $n? Нужно напасть раньше, чем это сделают Кровавые Парусы!'),
(664, 'ruRU', 'Бах, может, мне самому убить эту нагскую мерзость. Раз ты не собираешься.$b$bМожет, найду тебе вязальные спицы, чтоб ты $Gзанял:заняла; себя чем-нибудь.'),
(678, 'ruRU', 'Ты колеблешься. Почему? До сих пор ты $Gпоказывал:показывала; великую силу, $N. Не подведи меня сейчас.'),
(679, 'ruRU', 'Вижу, твоя смелость наконец иссякла. Похоже, мои предчувствия были верны: твоя сила ничто в сравнении с твоей бравадой.$b$bВернись ко мне, когда голова зверя будет отрублена, или не возвращайся никогда.'),
(681, 'ruRU', '$N, с каждым часом наша власть над Стромгардом слабеет. Тебе нужно спешить, иначе город непременно падет.'),
(745, 'ruRU', 'Если бы Бледногривы больше уважали землю и ее обитателей, этого конфликта бы не случилось.'),
(758, 'ruRU', 'Колодец Громового Рога по-прежнему осквернен, $N. Прошу, ты должен совершить обряд!'),
(877, 'ruRU', 'Ты $Gбыл:была; в Застывшем оазисе? Есть ли под его водами трещина?'),
(905, 'ruRU', 'Ты уже $Gпобывал:побывала; у гнезд, $N?'),
(1048, 'ruRU', 'Может, я недостаточно ясно выразился, $c. Я хочу, чтобы верховный инквизитор Вайтмейн была убита раз и навсегда. И заодно убери ее главных помощников.$b$bУбей этого фанатика, командира Алого ордена Могрейна. Сокруши Ирода, защитника Алого ордена. И перебей псаря Локси и его грязных псов.$b$bА теперь прочь!'),
(1062, 'ruRU', 'Долина Высокого леса лежит на северо-западе, $N.  Иди. Посей страх в тех, кто хочет разграбить эту землю!'),
(1192, 'ruRU', 'Я хочу использовать индурий в разных частях наших гонщиков, но для этого мне нужно много сырого индурия.$b$bИндуриевую руду можно найти на раскопках Ульдамана в Бесплодных землях, за морем в Кхаз Модане.$b$bГномы тоже получают его, поэтому нужно добывать свой, чтобы не отстать от них.'),
(1393, 'ruRU', 'Замочная скважина этого сундука забита черной смолой. Открыть его невозможно.'),
(1658, 'ruRU', 'Ты уже $Gподнимался:поднималась; в Тирисфальские леса и все $Gпроверил:проверила;? Обычно праздник проводят неподалеку от Подгорода…'),
(1678, 'ruRU', '$GБыл:Была; ли ты в хижине Веджрека, $N? Это от тебя разит вонью $R?'),
(1690, 'ruRU', 'Так скоро $Gвернулся:вернулась;?  Надеюсь, тебе удалось устроить гоблинское правосудие тем разбойникам и ворам из шайки Скитальцев Пустыни, как я просил!'),
(1803, 'ruRU', 'Возможно, ты гоняешься за сказками, $n, но правду можно найти в основе даже самых невероятных слухов.'),
(1878, 'ruRU', 'Снова здесь, $n?  Если у тебя есть еще пять водяных мешков Скитальцев Пустыни, то у меня для тебя найдется посылка!'),
(2520, 'ruRU', 'Ты $Gположил:положила; жертву у фонтана, $N?'),
(3083, 'ruRU', 'Добро пожаловать в Долину Испытаний, $N. Тебя бы здесь не было, не раздобудь ты мою табличку, так что перейду к делу.$B$BЯ Руаг и отвечаю за обучение разбойников, воров и карманников в Долине. Именно ко мне обратится Рука, если ты не будешь готов к тому, что тебя ждет. Но не волнуйся: Рука не станет управлять каждым твоим шагом, хотя с ними разумнее сотрудничать, если им понадобятся твои таланты.'),
(3092, 'ruRU', 'Добро пожаловать в лагерь Нараче, $N. Я слышал о тебе много хорошего. В тебе течет сильная кровь, и многие старейшины считают тебя уже умелым. Но мы это проверим.$B$BРавнины Мулгора станут твоим домом на некоторое время – постарайся изучить их как следует. Однажды ты отправишься в незнакомые земли, чтобы овладеть большим мастерством. Ты должен быть готов.'),
(4261, 'ruRU', 'Что ты $Gвидел:видела; в этой оскверненной земле?'),
(4803, 'ruRU', 'В Зимних Ключах ты найдешь больших медведей с очень толстой шкурой. Эти щербозубы получают сильную защиту от того, что способны выдержать. Если хочешь получить сопротивление огню, принеси мне Э''ко, что найдешь у щербозубов.$B$BПомни, у тебя в сумке должен лежать Сокровище Мау''ари, если хочешь охотиться за Э''ко.\r\n'),
(4804, 'ruRU', 'В Зимних Ключах ты будешь сражаться с большими летучими созданиями, которых зовут стылодыхи. Эти твари владеют силой магии льда. Если хочешь получить сопротивление магии льда, принеси мне Э''ко, что найдешь у стылодыхов.$B$BПомни, у тебя в сумке должен лежать Сокровище Мау''ари, если хочешь охотиться за Э''ко.\r\n'),
(4805, 'ruRU', 'В Зимних Ключах ты будешь сражаться с большими созданиями, которых зовут йети с холмов Ледополоха. Эти твари двигаются медленно, но от многих ударов уклоняются благодаря защите густой шерсти. Если хочешь получить умение уклоняться от атак, принеси мне Э''ко, что найдешь у них.$B$BПомни, у тебя в сумке должен лежать Сокровище Мау''ари, если хочешь охотиться за Э''ко.\r\n'),
(4807, 'ruRU', 'В Зимних Ключах ты будешь сражаться с могучими существами, которые, кажется, обладают врожденной магией. Эти дикие совухи способны на сильные чары. Если хочешь увеличить свой интеллект, принеси мне Э''ко, что найдешь у любого из диких совухов.$B$BПомни, у тебя в сумке должен лежать Сокровище Мау''ари, если хочешь охотиться за Э''ко.\r\n'),
(4921, 'ruRU', 'Ты $Gнашел:нашела; хоть какой-нибудь ее след? Боль в груди говорит, что случилось худшее, но я надеюсь, что ты найдешь ее целой и невредимой.'),
(5092, 'ruRU', 'Готовься к худшему, $N, соберись с силами.  Задание перед нами будет нелегким. Пока мы собираем здесь войска, чтобы нанести удар по Плети, ты будешь в передовом отряде, который начнет бой! Твоя задача на Холме Скорби положит начало нашему пути к победе!'),
(5097, 'ruRU', 'Как только башни будут отмечены, они станут главными целями нашей атаки на Андорал.  Полагаю, когда мы нейтрализуем башни, проявится главная угроза Андорала. Дальше нас ждет прямая схватка за город!$B$BТы $Gвернулся:вернулась; доложить об успехе, да?  Не забудь и сигнальный факел; нам нужно сохранить контроль над снаряжением.'),
(5098, 'ruRU', 'Как только башни будут отмечены, они станут главными целями нашей атаки на Андорал.  Полагаю, когда мы нейтрализуем башни, проявится главная угроза Андорала. Дальше нас ждет прямая схватка за город!$B$BТы $Gвернулся:вернулась; доложить об успехе, да?  Не забудь и сигнальный факел; нам нужно сохранить контроль над снаряжением.'),
(5126, 'ruRU', '…'),
(5536, 'ruRU', 'Как твоя битва с сатирами, $c?$B$BОни так сильны, как ты $Gдумал:думала;? Сильнее? Или совсем не ровня твоей мощи?'),
(5728, 'ruRU', 'Ты уже $Gнашел:нашела; их, $N? Главарей Пылающего Клинка.$B$BЯ знал, что Совет Теней хочет отнять у меня Оргриммар и всю Орду, но не понимал, как быстро они сумели проникнуть в город. У этого чудища столько рук… мы можем отрубать их, пока оно не выдохнется, но не продвинемся дальше, чем в начале. Придется велеть моим шпионам удвоить усилия.'),
(6461, 'ruRU', 'Эй, мон, ты $Gприкончил:прикончила; тех мохнатых кровопийц? Я здесь, в Каменном Когте, никого не боюсь, но по ночам не гуляю… ты понимаешь, о чем я, мон!$B$BПока я не попадаю им на обеденный стол, все хорошо.$B$BУдачи тебе, $c!'),
(6482, 'ruRU', 'Ты не $Gвидел:видела; моего брата Руула? Он ушел в лес несколько дней назад и не вернулся…'),
(6861, 'ruRU', 'Мне не терпится испытать мой портативный измельчитель так же, как и тебе, $r, но чтобы собрать набор, мне нужны материалы – очень много материалов! \r\n\r\nТочнее, мне нужна гора тория, мифрила и железа. Еще мне потребуется по одной паровой пиле на каждый измельчитель. Их придется взять на лесопилке. \r\n\r\nКогда я здесь вынюхивал (до того, как меня схватили), я заметил груду паровых пил в лагере лесорубов Грозовой Вершины. \r\n\r\nМастер-инженер Спустипар просит принести ему следующее:'),
(6862, 'ruRU', 'Мне не терпится испытать мой портативный измельчитель так же, как и тебе, $r, но чтобы собрать набор, мне нужны материалы – очень много материалов! \r\n\r\nТочнее, мне нужна гора тория, мифрила и железа. Еще мне потребуется по одной паровой пиле на каждый измельчитель. Их придется взять на лесопилке. \r\n\r\nКогда я здесь вынюхивал (до того, как меня схватили), я заметил груду паровых пил в лагере лесорубов Грозовой Вершины. \r\n\r\nМастер-инженер Спустипар просит принести ему следующее:'),
(6901, 'ruRU', 'Мои войска снабжены и готовы к штурму. Нам нужен только приказ интенданта клана Северного Волка, и я брошу их в бой!'),
(7364, 'ruRU', 'Хорошенько их проучи, $N. Пусть знают: гномы не позволят себя запугивать!'),
(7365, 'ruRU', 'Я все еще чувствую вонь этих троллей.'),
(7382, 'ruRU', 'Ты $Gубил:убила; Коррака Кровопуска, $c? По донесениям разведчиков, он где-то рядом с Полем Раздора.'),
(7402, 'ruRU', 'Тебе нужны щипцы, чтобы выдернуть им зубы?'),
(7424, 'ruRU', 'Хорошенько их проучи, $N. Пусть знают: гномы не позволят себя запугивать!'),
(7425, 'ruRU', 'Я все еще чувствую вонь этих троллей.'),
(7428, 'ruRU', 'Тебе нужны щипцы, чтобы выдернуть им зубы?'),
(7653, 'ruRU', 'За чертежи пояса мне нужно 20 слитков тория.'),
(7654, 'ruRU', 'За чертежи сапог мне нужно 40 слитков тория. Ага, сорок. Что, заплачешь? Дать платочек?$B$B<Деротайн смеется.>'),
(7655, 'ruRU', 'За чертежи наручей мне нужно 20 слитков тория.$B$BТы в порядке, сынок? Что-то ты весь красный.'),
(7656, 'ruRU', 'За чертежи нагрудника мне нужно 60 слитков тория.$B$B$BЭх, ты опять за свое. Побежишь жаловаться своим синим богам, спрашивать, за что они тебя оставили?!? Закаляйся, неженка! Никто не говорил, что жизнь справедлива.'),
(7657, 'ruRU', 'Выложи 50 слитков тория, и чертежи шлема твои.'),
(7658, 'ruRU', 'Выложи 60 слитков тория, и чертежи поножей твои.$B$BЗнаю, знаю, я довожу тебя до банкротства! Я такое уже слышал сто раз, так что оставь свои жалобы при себе, слабак.'),
(7659, 'ruRU', 'За чертежи наплечников мне нужно 20 слитков тория.'),
(7788, 'ruRU', 'Ты сражался в Ущелье Песни Войны и защищал Крепость Среброкрылых?'),
(7791, 'ruRU', 'Мы сейчас принимаем пожертвования шерстяной ткани. Пожертвование шестидесяти кусков шерстяной ткани принесет тебе полное признание Штормграда за щедрость. Запасы шерсти у нас такие, что нужно всего шестьдесят кусков от тебя; остальное, думаю, мы сможем собрать у других жителей королевства.$B$BЕсли у тебя при себе шестьдесят кусков шерстяной ткани и ты $Gготов:готова; их пожертвовать, я могу забрать их прямо сейчас.'),
(7792, 'ruRU', 'Мы сейчас принимаем пожертвования шерстяной ткани. Пожертвование шестидесяти кусков шерстяной ткани принесет тебе полное признание Дарнаса за щедрость. Запасы шерсти у нас такие, что нужно всего шестьдесят кусков от тебя; остальное, думаю, мы сможем собрать у других жителей королевства.$B$BЕсли у тебя при себе шестьдесят кусков шерстяной ткани и ты $Gготов:готова; их пожертвовать, я могу забрать их прямо сейчас.'),
(7871, 'ruRU', 'Ты сражался в Ущелье Песни Войны и защищал Крепость Среброкрылых?'),
(7872, 'ruRU', 'Ты сражался в Ущелье Песни Войны и защищал Крепость Среброкрылых?'),
(7873, 'ruRU', 'Ты сражался в Ущелье Песни Войны и защищал Крепость Среброкрылых?'),
(8105, 'ruRU', '$N, ты еще не $Gатаковал:атаковала; все четыре базы. Вернись ко мне, когда выполнишь все задачи.'),
(8123, 'ruRU', 'В чем дело, $R? У тебя есть знаки чести? Возвращайся в Низину Арати, убивай альянсовскую мразь и отбирай ее ресурсы для Темной Госпожи!'),
(8160, 'ruRU', 'В чем дело, $R? У тебя есть знаки чести? Возвращайся в Низину Арати, убивай альянсовскую мразь и отбирай ее ресурсы для Темной Госпожи!'),
(8161, 'ruRU', 'В чем дело, $R? У тебя есть знаки чести? Возвращайся в Низину Арати, убивай альянсовскую мразь и отбирай ее ресурсы для Темной Госпожи!'),
(8162, 'ruRU', 'В чем дело, $R? У тебя есть знаки чести? Возвращайся в Низину Арати, убивай альянсовскую мразь и отбирай ее ресурсы для Темной Госпожи!'),
(8266, 'ruRU', 'Я знаю, что в Ущелье Песни Войны порой нелегко выйти победителем. И все же твои усилия ради нас, даже без победы, очень важны.$B$BЕсли ты пройдешь одно из испытаний в Ущелье Песни Войны, но не одержишь победы, ты все равно получишь ленту самопожертвования. Принеси ее мне, чтобы Часовые смогли наградить тебя за то, что ты действовал от нашего имени… даже если на этот раз победа не далась.'),
(8268, 'ruRU', 'Я знаю, что в Ущелье Песни Войны порой нелегко выйти победителем. И все же твои усилия ради нас, даже без победы, очень важны.$B$BЕсли ты пройдешь одно из испытаний в Ущелье Песни Войны, но не одержишь победы, ты все равно получишь ленту самопожертвования. Принеси ее мне, чтобы Разведчики смогли наградить тебя за то, что ты действовал от нашего имени… даже если на этот раз победа не далась.'),
(8291, 'ruRU', 'Ты сражался в Ущелье Песни Войны и защищал Крепость Среброкрылых?'),
(8292, 'ruRU', 'За прошлое задание тебе зачтено. Принеси мне еще знаков чести, и получишь награду.'),
(8293, 'ruRU', 'За прошлое задание тебе зачтено. Принеси мне еще знаков чести, и получишь награду.'),
(8299, 'ruRU', 'В чем дело, $R? У тебя есть знаки чести? Возвращайся в Низину Арати, убивай альянсовскую мразь и отбирай ее ресурсы для Темной Госпожи!'),
(8373, 'ruRU', 'Эти проклятые Отрекшиеся… мало того что они нежить, так еще и бузят и устраивают неприятности в МОЕЙ деревне!'),
(8383, 'ruRU', 'Битва в Альтеракской долине продолжается, $N!  Ты $Gвложил:вложила; свою долю в последнее время, $N?'),
(8384, 'ruRU', 'Война с Ордой быстро истощает наши запасы, $N.  Крайне важно удерживать Низину Арати, чтобы ресурсы продолжали поступать!  Ты уже $Gпомог:помога; в Арати?'),
(8390, 'ruRU', 'Война с альянсовской мразью требует ресурсов, $n! Мы не можем допустить, чтобы наши запасы иссякли посреди битвы.  Продолжай следить, чтобы Низина Арати оставалась в наших руках!'),
(8391, 'ruRU', 'Война с Ордой быстро истощает наши запасы, $N.  Крайне важно удерживать Низину Арати, чтобы ресурсы продолжали поступать!  Ты уже $Gпомог:помога; в Арати?'),
(8392, 'ruRU', 'Война с Ордой быстро истощает наши запасы, $N.  Крайне важно удерживать Низину Арати, чтобы ресурсы продолжали поступать!  Ты уже $Gпомог:помога; в Арати?'),
(8397, 'ruRU', 'Война с Ордой быстро истощает наши запасы, $N.  Крайне важно удерживать Низину Арати, чтобы ресурсы продолжали поступать!  Ты уже $Gпомог:помога; в Арати?'),
(8398, 'ruRU', 'Война с Ордой быстро истощает наши запасы, $N.  Крайне важно удерживать Низину Арати, чтобы ресурсы продолжали поступать!  Ты уже $Gпомог:помога; в Арати?'),
(8440, 'ruRU', 'Война с альянсовской мразью требует ресурсов, $n! Мы не можем допустить, чтобы наши запасы иссякли посреди битвы.  Продолжай следить, чтобы Низина Арати оставалась в наших руках!'),
(8441, 'ruRU', 'Война с альянсовской мразью требует ресурсов, $n! Мы не можем допустить, чтобы наши запасы иссякли посреди битвы.  Продолжай следить, чтобы Низина Арати оставалась в наших руках!'),
(8442, 'ruRU', 'Война с альянсовской мразью требует ресурсов, $n! Мы не можем допустить, чтобы наши запасы иссякли посреди битвы.  Продолжай следить, чтобы Низина Арати оставалась в наших руках!'),
(8443, 'ruRU', 'Война с альянсовской мразью требует ресурсов, $n! Мы не можем допустить, чтобы наши запасы иссякли посреди битвы.  Продолжай следить, чтобы Низина Арати оставалась в наших руках!'),
(8461, 'ruRU', 'Когда ты заслужишь доверие Древобрюхов, уверен, мы сможем что-нибудь для тебя сделать. Древобрюхи не забывают союзников, особенно в такие темные времена.'),
(8464, 'ruRU', 'Мы очень ценим то, что ты $Gсделал:сделала; для Древобрюхов, $N. Твои дальнейшие усилия непременно принесут тебе доверие и уважение моего племени.'),
(8550, 'ruRU', 'Здравствуй снова, $n. Я рад, что ты опять $Gпришел:пришла; поговорить о нашей нескончаемой потребности в мирном цвете. Военные усилия продолжаются, а с ними и производство зелий и эликсиров для грядущих сражений. Поможешь нам еще раз, $C? Мне нужно столько же мирного цвета, сколько и в прошлый раз, так что если соберешь его и вернешься сюда, я буду очень признателен. Конечно, если он уже при тебе, я с радостью приму его прямо сейчас'),
(8579, 'ruRU', 'Мы чувствуем присутствие наших порабощенных собратьев в глубине Ан''Киража, но даже армии драконов не хватило бы, чтобы их спасти, $r.$B$BТо же заклятие, что заточило их, вверит нас власти К''Туна, если мы подойдем к нему ближе.$B$BДревний бог предвидел наше появление. Надежды нет. Что может изменить простой смертный вроде тебя?'),
(8581, 'ruRU', 'Пеле''кейки знает: ты пришел помогать. Принеси много огнецвета, и он будет очень рад. Пеле''кейки, может, сделает из огнецвета большие бомбы. Бросать на насекомых с летучей мыши над Ан''Киражем, когда придет война. Но Пеле''кейки нужно больше огнецвета, $c!$B$BТы принесешь Пеле''кейки огнецвет, и быстро. Приходи, когда будет не меньше, чем в прошлый раз, и Пеле''кейки будет доволен.'),
(8601, 'ruRU', 'Подготовка к грядущей войне в Ан''Кираже идет полным ходом, $c. Но чтобы мы не отстали, или хотя бы чтобы не я был тем, кто задержит остальных, мне нужна еще одна стопка грубой кожи. Твоя расторопность в этом деле будет высоко оценена, $N.'),
(8605, 'ruRU', 'Рад тебя снова видеть, $C. Мы все еще готовимся к военным усилиям, и мне пригодится любая помощь в сборе шерстяных бинтов. Любая поддержка будет оценена. Надеюсь лишь, что наших усилий хватит. Я потерял слишком много благородных душ на вчерашних полях сражений, чтобы не сделать все возможное, чтобы этого не повторилось.'),
(8608, 'ruRU', 'Ты $Gвернулся:вернулась;? Любопытно. Как видишь, я все еще собираю припасы для «военных усилий» против Ан''Киража. Это значит, что тебе нужно снова пойти и собрать для меня стопку бинтов из магической ткани. Жду твоего возвращения, $c.'),
(8610, 'ruRU', 'Все ближе время, когда мы очертя голову бросимся в пламя битвы при Ан''Кираже, жрец. Но сначала нужно собрать силы и подготовиться, чтобы выдержать натиск насекомых и их повелителей.$B$BЕсли ты снова здесь, то наверняка хочешь сделать еще один вклад в военные усилия – принести бинты из рунной ткани? Сделай это как можно скорее и вернись ко мне.'),
(8612, 'ruRU', 'Как видишь, $c, нам нужно упаковать еще больше еды для солдат. Не знаю, $Gбывал:бывала; ли ты на войне, но когда проходит первый шок от поля боя, можно здорово проголодаться.  В прошлый раз ты отлично $Gсправился:справилась;, так что надеюсь, что и теперь ты принесешь еще одну стопку постных волчьих стейков, и, может, чуть быстрее.'),
(8614, 'ruRU', 'Как видишь, нам все еще нужно много рыбки. Бойцам в грядущей войне при Ан''Кираже понадобится много еды, так что мне нужно все пятнистые желтохвосты, какие есть. Ты ловишь, готовишь и приносишь сюда, а я благодарю тебя, и Орда благодарит.'),
(8616, 'ruRU', 'Прошлая партия запеченного лосося, которую ты $Gпожертвовал:пожертвовала; на военные нужды, выглядела очень аппетитно, $C. Признаюсь, мне хотелось взять пару кусков себе. Как видишь, норму мы еще не набрали. Надеюсь, ты $Gвернулся:вернулась; с еще одной стопкой запеченного лосося'),
(8742, 'ruRU', 'Прошла тысяча лет, и, как и было суждено, передо мной стоит тот, кто поведет свой народ в новую эпоху.$B$BДревний бог дрожит, $N. О да, он боится твоей веры. Разбей пророчество К''Туна.$B$BОн знает, что ты идешь, защитник, – а с тобой идет мощь Калимдора. Тебе нужно лишь дать мне знать, что ты $Gготов:готова;, и я вручу тебе Скипетр Зыбучих Песков.'),
(8846, 'ruRU', 'А, $Gпришел:пришла; за дополнительными припасами для себя? Что ж, я понимаю нужду в дополнительном снаряжении… достаточно оглядеться, чтобы в этом убедиться.$B$BЯ выдам тебе еще припасов, но взамен нужно принести подходящее количество благодарственных печатей. Признания за такой обмен ты не получишь, но, возможно, найдешь для себя что-нибудь полезное, что поможет тебе выжить, когда наконец начнется сражение.'),
(8847, 'ruRU', 'А, $Gпришел:пришла; за дополнительными припасами для себя? Что ж, я понимаю нужду в дополнительном снаряжении… достаточно оглядеться, чтобы в этом убедиться.$B$BЯ выдам тебе еще припасов, но взамен нужно принести подходящее количество благодарственных печатей. Признания за такой обмен ты не получишь, но, возможно, найдешь для себя что-нибудь полезное, что поможет тебе выжить, когда наконец начнется сражение.'),
(8848, 'ruRU', 'А, $Gпришел:пришла; за дополнительными припасами для себя? Что ж, я понимаю нужду в дополнительном снаряжении… достаточно оглядеться, чтобы в этом убедиться.$B$BЯ выдам тебе еще припасов, но взамен нужно принести подходящее количество благодарственных печатей. Признания за такой обмен ты не получишь, но, возможно, найдешь для себя что-нибудь полезное, что поможет тебе выжить, когда наконец начнется сражение.'),
