INSERT INTO `gossip_menu_option_locale` (`MenuID`, `OptionID`, `Locale`, `OptionText`, `BoxText`) VALUES
(3984, 4, 'ruRU', '<Взять письмо>', NULL),
(39690, 0, 'ruRU', 'С какими опасностями здесь сталкиваются братья и сестры из крепости Бандариона, Андер?', NULL),
(39691, 0, 'ruRU', 'Чем ты здесь занимаешься, Хильда?', NULL),
(39692, 0, 'ruRU', 'Данита велела мне найти тебя. Чем ты занимаешься здесь, в крепости Бандариона?', NULL),
(40780, 0, 'ruRU', 'Я $Gготов:готова; сражаться, Аамелия.', NULL),
(40789, 0, 'ruRU', 'Просто так, спасибо, Альварион. Я $Gхотел:хотела; бы спросить о другом.', NULL),
(40790, 0, 'ruRU', 'Вопрос к тебе, Альварион. Для чего, по твоему опыту, используют пыльцу мотыльков?', NULL),
(40964, 0, 'ruRU', 'Острову Зефрис нужен Высший орден!  <Объяснить Элаадрину план Валенниа.>', NULL),
(41129, 0, 'ruRU', 'Хочу обучиться!', NULL),
