(41553, 0, 'ruRU', 'Белатаан! Ваятели ветра требуют объяснить, зачем ты снял детали с нашего творения в Валанаре!', NULL),
(41638, 0, 'ruRU', 'Я хочу поговорить о чем-нибудь другом.', NULL),
(41639, 0, 'ruRU', 'Я хочу поговорить о чем-нибудь другом.', NULL),
(41640, 0, 'ruRU', 'Я хочу поговорить о чем-нибудь другом.', NULL),
(41641, 0, 'ruRU', 'Что такое перехваченные ящики с припасами?', NULL),
(41641, 1, 'ruRU', 'Что такое ремесленные патенты?', NULL),
(41641, 2, 'ruRU', 'Золото у вас основная валюта?', NULL),
