INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES
(620, 2, 0, 'ruRU', '%s начинает клевать корм.'),
(4832, 1, 0, 'ruRU', 'Спи…'),
(9019, 0, 0, 'ruRU', 'На помощь Трону!'),
(9999, 6, 0, 'ruRU', '%s встает после короткой паузы.'),
(9999, 8, 0, 'ruRU', '%s исчезает после долгой паузы.'),
(11382, 0, 0, 'ruRU', 'Я скормлю ваши души самому Хаккару!'),
(11382, 2, 0, 'ruRU', 'Я слежу за тобой, $N!'),
(11382, 3, 0, 'ruRU', 'Не зли меня. Тебе не понравится, когда я в гневе.'),
(11948, 2, 0, 'ruRU', 'Скажу лишь одно… Альтеракская долина будет нашей.'),
(14510, 0, 0, 'ruRU', 'Приведи меня к своей хозяйке паутины, Шадре. Выпусти свой яд!'),
(14627, 0, 0, 'ruRU', 'Вот это называется тяжелая рука!'),
(15263, 0, 1, 'ruRU', 'Трепещите, смертные! Грядет эпоха тьмы.'),
(15263, 0, 2, 'ruRU', 'Дрожите! Вам пришел конец.'),
(15263, 1, 1, 'ruRU', 'Бесхребетные ничтожества! Вы утонете в реках крови!'),
(15263, 1, 2, 'ruRU', 'Воздух наполнится криками умирающих. Начинается симфония ужаса!'),
(15263, 2, 0, 'ruRU', 'Готовьтесь к возвращению древних!'),
(15339, 0, 0, 'ruRU', 'Я обновлен!'),
(15339, 0, 1, 'ruRU', 'Мои силы обновились!'),
(15339, 0, 2, 'ruRU', 'Мои силы возвращаются!'),
(15339, 1, 0, 'ruRU', 'Защищайте город любой ценой!'),
(15339, 1, 1, 'ruRU', 'По местам. Защищайте город.'),
(15339, 1, 2, 'ruRU', 'Нарушители будут уничтожены.'),
(15936, 3, 0, 'ruRU', 'Не-е-ет…'),
(15990, 1, 0, 'ruRU', 'Хорошо, что вы служите мне так преданно. Скоро все будут служить Королю-личу, и в конце концов вы будете вознаграждены… если не дрогнете.'),
(15990, 3, 0, 'ruRU', 'Ваши меры безопасности не сработали! Немедленно разберитесь с этой помехой!'),
(15990, 15, 1, 'ruRU', 'Довольно! Мне надоели эти помехи!'),
(15990, 15, 2, 'ruRU', 'Глупцы, вы слишком распылили свои силы. Свободны, мои слуги!'),
(15990, 16, 0, 'ruRU', 'Кто смеет нарушить покой моих владений? Знайте: все, кто сюда вторгся, обречены.'),
(250282, 0, 0, 'ruRU', '%s в страхе пытается убежать!'),
(250283, 0, 0, 'ruRU', '%s в страхе пытается убежать!'),
(250656, 0, 0, 'ruRU', '%s приходит в ярость!'),
(250657, 0, 0, 'ruRU', 'Какие заблудшие и несчастные души…'),
(250657, 1, 0, 'ruRU', 'Даже в смерти… я не сдамся.'),
(250660, 0, 0, 'ruRU', 'Свежее мясо на плаху!'),
(250660, 1, 0, 'ruRU', 'Прости меня, Лордерон…'),
(250874, 0, 0, 'ruRU', '%s приходит в ярость!'),
(250921, 0, 0, 'ruRU', 'Крошечный дух испуганно пищит и исчезает!'),
(251451, 1, 0, 'ruRU', '%s в страхе пытается убежать!'),
(251451, 2, 0, 'ruRU', 'Покорись воле повелителя ветров и моли его о прощении!'),
(251966, 0, 0, 'ruRU', 'Только праведные будут спасены от грядущего! Смерть неверным!'),
(252481, 0, 0, 'ruRU', 'Крошечный дух испуганно пищит и исчезает!'),
(252764, 0, 0, 'ruRU', '%s в страхе пытается убежать!'),
(256306, 1, 0, 'ruRU', 'Поездка иногда бывает ухабистой, поэтому при перемещении между плоскостями бытия рекомендуется крепко за что-нибудь держаться.'),
(256966, 1, 0, 'ruRU', 'Вам не остановить великое дело Лортуны! Воля повелителя ветров исполнена!'),
(257532, 9, 0, 'ruRU', 'Тайная магия оскорбляет духов ветра!'),
(259433, 0, 0, 'ruRU', 'Я этого не приму! Я служу Свету!'),
(259433, 1, 0, 'ruRU', 'Свет очистит нас обоих!'),
(259434, 0, 0, 'ruRU', 'Свет очистит нас обоих!'),
(259434, 1, 0, 'ruRU', 'Гори в праведном пламени, мерзкое чудовище!'),
(265701, 0, 0, 'ruRU', 'Engoth Nagan waldir! Far Gothalgos!'),
(272101, 0, 0, 'ruRU', 'Я удвою усилия.'),
(275270, 0, 0, 'ruRU', 'Мулгорский неборез прибыл! Все на борт, отправление в Мулгор!'),
(275954, 0, 0, 'ruRU', 'Еретики собирались судить меня за мои преступления – полагаю, за само мое существование.'),
(275954, 1, 0, 'ruRU', 'Кажется, я злоупотребил гостеприимством. Давай уйдем отсюда.'),
(275954, 2, 0, 'ruRU', 'Иди по этой тропе к крепости Бандариона, если хочешь. Там стоят другие такие же, как я.'),
(275954, 3, 0, 'ruRU', 'Брилл в той стороне. Идем дальше.'),
(275954, 4, 0, 'ruRU', 'Дальше я дойду сам. Передай Шари Стилвелл, что я в безопасности. Мне сначала нужно уладить одно небольшое дело.')
